import React, { useState, useEffect } from 'react';
import {
  getConfigurations,
  createConfiguration,
  updateConfiguration,
  deleteConfiguration
} from '../services/api';
import './Pages.css';

export default function Configuration() {
  const [configs, setConfigs] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({
    key: '',
    value: '',
    description: '',
    category: 'system'
  });

  useEffect(() => {
    fetchConfigs();
  }, []);

  const fetchConfigs = async () => {
    try {
      const res = await getConfigurations();
      setConfigs(res.data);
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await createConfiguration(form);
      setForm({
        key: '',
        value: '',
        description: '',
        category: 'system'
      });
      setShowForm(false);
      fetchConfigs();
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('¿Estás seguro?')) {
      try {
        await deleteConfiguration(id);
        fetchConfigs();
      } catch (err) {
        console.error('Error:', err);
      }
    }
  };

  return (
    <div className="page">
      <h2>⚙️ Configuración del Sistema</h2>

      <button onClick={() => setShowForm(!showForm)} className="btn-primary">
        {showForm ? 'Cancelar' : '+ Nueva Configuración'}
      </button>

      {showForm && (
        <form onSubmit={handleSubmit} className="form-container">
          <input
            type="text"
            placeholder="Clave"
            value={form.key}
            onChange={(e) => setForm({ ...form, key: e.target.value })}
            required
          />
          <input
            type="text"
            placeholder="Valor"
            value={form.value}
            onChange={(e) => setForm({ ...form, value: e.target.value })}
            required
          />
          <select
            value={form.category}
            onChange={(e) => setForm({ ...form, category: e.target.value })}
          >
            <option value="system">Sistema</option>
            <option value="email">Email</option>
            <option value="security">Seguridad</option>
          </select>
          <textarea
            placeholder="Descripción"
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
          />
          <button type="submit" className="btn-success">Crear</button>
        </form>
      )}

      <table className="table">
        <thead>
          <tr>
            <th>Clave</th>
            <th>Valor</th>
            <th>Categoría</th>
            <th>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {configs.map((c) => (
            <tr key={c.id}>
              <td>{c.key}</td>
              <td>{c.value}</td>
              <td>{c.category}</td>
              <td>
                <button className="btn-danger" onClick={() => handleDelete(c.id)}>
                  Eliminar
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
